public sealed class ScreenTarget { public string Device,Path,Label; public uint AdapterLow,Id;public int AdapterHigh; }
public sealed class HdrInfo {public bool Supported,Enabled;}
[StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]
public struct VideoMode {
 [MarshalAs(UnmanagedType.ByValTStr,SizeConst=32)]public string DeviceName;
 public ushort SpecVersion,DriverVersion,Size,DriverExtra;public uint Fields;
 public int X,Y;public uint Orientation,FixedOutput;public short Color,Duplex,YResolution,TTOption,Collate;
 [MarshalAs(UnmanagedType.ByValTStr,SizeConst=32)]public string FormName;
 public ushort LogPixels;public uint Bits,Width,Height,Flags,Frequency,ICMMethod,ICMIntent,MediaType,DitherType,Reserved1,Reserved2,PanningWidth,PanningHeight;
 public override string ToString(){return Width+" × "+Height+"  ·  "+Frequency+" Hz";}
 public string Key {get{return Width+"x"+Height+"@"+Frequency;}}
}
internal static class VideoNative {
 [DllImport("user32.dll",EntryPoint="DisplayConfigGetDeviceInfo")]static extern int GetInfo(IntPtr data);
 [DllImport("user32.dll",EntryPoint="DisplayConfigSetDeviceInfo")]static extern int SetInfo(IntPtr data);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern bool EnumDisplaySettings(string device,int index,ref VideoMode mode);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int ChangeDisplaySettingsEx(string device,ref VideoMode mode,IntPtr window,uint flags,IntPtr parameter);
 static byte[] Info(uint type,int size,ScreenTarget target,bool set,out int result){var bytes=new byte[size];Put(bytes,0,type);Put(bytes,4,(uint)size);Put(bytes,8,target.AdapterLow);Put(bytes,12,unchecked((uint)target.AdapterHigh));Put(bytes,16,target.Id);var ptr=Marshal.AllocHGlobal(size);try{Marshal.Copy(bytes,0,ptr,size);result=set?SetInfo(ptr):GetInfo(ptr);Marshal.Copy(ptr,bytes,0,size);return bytes;}finally{Marshal.FreeHGlobal(ptr);}}
 static void Put(byte[] b,int offset,uint value){Array.Copy(BitConverter.GetBytes(value),0,b,offset,4);}
 public static List<ScreenTarget> Targets(){var c=NativeDisplay.Capture();var result=new List<ScreenTarget>();for(int i=0;i<c.PathCount;i++){int p=i*72;var source=new ScreenTarget{AdapterLow=BitConverter.ToUInt32(c.Paths,p),AdapterHigh=BitConverter.ToInt32(c.Paths,p+4),Id=BitConverter.ToUInt32(c.Paths,p+8)};int code;var name=Info(1,84,source,false,out code);if(code!=0)continue;var target=new ScreenTarget{Device=Encoding.Unicode.GetString(name,20,64).TrimEnd('\0'),AdapterLow=BitConverter.ToUInt32(c.Paths,p+20),AdapterHigh=BitConverter.ToInt32(c.Paths,p+24),Id=BitConverter.ToUInt32(c.Paths,p+28)};name=Info(2,420,target,false,out code);if(code!=0)continue;target.Label=Encoding.Unicode.GetString(name,36,128).TrimEnd('\0');target.Path=Encoding.Unicode.GetString(name,164,256).TrimEnd('\0');result.Add(target);}return result;}
 public static ScreenTarget Target(string device){var matches=Targets().Where(t=>string.Equals(t.Device,device,StringComparison.OrdinalIgnoreCase)).ToList();if(matches.Count!=1)throw new InvalidOperationException("The TV must be connected in extended display mode.");return matches[0];}
 public static ScreenTarget Resolve(ScreenTarget saved){var target=Targets().SingleOrDefault(t=>string.Equals(t.Path,saved.Path,StringComparison.OrdinalIgnoreCase));if(target==null)throw new InvalidOperationException("Reconnect the TV to restore its video settings.");return target;}
 public static HdrInfo Hdr(ScreenTarget target){int code;var info=Info(15,36,target,false,out code);if(code==0){uint bits=BitConverter.ToUInt32(info,20);return new HdrInfo{Supported=(bits&16)!=0&&(bits&8)==0,Enabled=(bits&32)!=0};}info=Info(9,32,target,false,out code);if(code!=0)return new HdrInfo();uint old=BitConverter.ToUInt32(info,20);return new HdrInfo{Supported=(old&1)!=0&&(old&12)==0,Enabled=(old&2)!=0};}
 public static void Hdr(ScreenTarget target,bool on){if(!Hdr(target).Supported)throw new InvalidOperationException("HDR is unavailable for this TV and connection.");int code=WriteHdr(target,16,on);if(code==87||code==50)code=WriteHdr(target,10,on);if(code!=0)throw new InvalidOperationException("Windows could not change HDR ("+code+").");for(int i=0;i<12;i++){if(Hdr(Resolve(target)).Enabled==on)return;Thread.Sleep(150);}throw new InvalidOperationException("Windows did not confirm the HDR change.");}
 static int WriteHdr(ScreenTarget target,uint type,bool on){var data=new byte[24];Put(data,0,type);Put(data,4,24);Put(data,8,target.AdapterLow);Put(data,12,unchecked((uint)target.AdapterHigh));Put(data,16,target.Id);Put(data,20,on?1u:0u);var ptr=Marshal.AllocHGlobal(24);try{Marshal.Copy(data,0,ptr,24);return SetInfo(ptr);}finally{Marshal.FreeHGlobal(ptr);}}
 static VideoMode Empty(){return new VideoMode{Size=(ushort)Marshal.SizeOf(typeof(VideoMode))};}
 public static VideoMode Current(string device){var m=Empty();if(!EnumDisplaySettings(device,-1,ref m))throw new InvalidOperationException("Windows could not read the TV display mode.");return m;}
 public static List<VideoMode> Modes(string device){var modes=new List<VideoMode>();for(int i=0;i<4096;i++){var m=Empty();if(!EnumDisplaySettings(device,i,ref m))break;if(m.Bits==32&&(m.Flags&2)==0&&m.Width>=800&&m.Height>=600&&m.Frequency>=24)modes.Add(m);}return modes.GroupBy(m=>m.Key).Select(g=>g.First()).OrderByDescending(m=>m.Width).ThenByDescending(m=>m.Height).ThenByDescending(m=>m.Frequency).ToList();}
 public static void Apply(ScreenTarget target,VideoMode choice){target=Resolve(target);var current=Current(target.Device);var candidate=Modes(target.Device).FirstOrDefault(m=>m.Key==choice.Key);if(candidate.Width==0)throw new InvalidOperationException("This resolution and refresh rate are no longer available.");current.Width=candidate.Width;current.Height=candidate.Height;current.Frequency=candidate.Frequency;current.Bits=candidate.Bits;current.Flags=candidate.Flags;current.Fields=0x1c0000|0x400000|0x200000;int code=ChangeDisplaySettingsEx(target.Device,ref current,IntPtr.Zero,2,IntPtr.Zero);if(code!=0)throw new InvalidOperationException("The TV rejected that display mode ("+code+").");code=ChangeDisplaySettingsEx(target.Device,ref current,IntPtr.Zero,4,IntPtr.Zero);if(code!=0)throw new InvalidOperationException("Windows could not apply that display mode ("+code+").");var actual=Current(Resolve(target).Device);if(actual.Key!=choice.Key)throw new InvalidOperationException("Windows selected a different display mode.");}
}
internal static class WindowsVrr {
 internal static string Path=@"Software\Microsoft\DirectX\UserGpuPreferences";const string Name="DirectXUserGlobalSettings";
 internal static string Read(){using(var key=Registry.CurrentUser.OpenSubKey(Path))return key==null?"":(key.GetValue(Name,"") as string??"");}
 internal static string Token(string value){var match=Regex.Match(value??"",@"(?:^|;)\s*(VRROptimizeEnable\s*=\s*[^;]*)",RegexOptions.IgnoreCase);return match.Success?match.Groups[1].Value:null;}
 internal static string Replace(string value,string token){var parts=(value??"").Split(';').Where(p=>p.Trim().Length>0&&!Regex.IsMatch(p,@"^\s*VRROptimizeEnable\s*=",RegexOptions.IgnoreCase)).ToList();if(token!=null)parts.Add(token);return string.Join(";",parts)+(parts.Count>0?";":"");}
 public static bool Enabled {get{return Regex.IsMatch(Token(Read())??"",@"=\s*1\s*$");}}
 public static void Set(string token){using(var key=Registry.CurrentUser.CreateSubKey(Path)){string text=Replace(Read(),token);if(text.Length==0)key.DeleteValue(Name,false);else key.SetValue(Name,text,RegistryValueKind.String);}if(Token(Read())!=token)throw new InvalidOperationException("Windows could not save the VRR preference.");}
}
public sealed class VideoRecovery {public ScreenTarget HdrTarget;public bool HdrBefore;public bool VrrSaved;public string VrrBefore;}
public sealed class VideoPending {public ScreenTarget Target;public VideoMode Mode;public bool IsHdr,Hdr;}
internal static class VideoSession {
 static readonly object gate=new object();
 static VideoRecovery Read(){return File.Exists(Storage.PathOf("video-session.json"))?Storage.Read<VideoRecovery>("video-session.json"):new VideoRecovery();}
 public static void RememberHdr(ScreenTarget target){lock(gate){var r=Read();if(r.HdrTarget!=null)return;r.HdrTarget=target;r.HdrBefore=VideoNative.Hdr(target).Enabled;Storage.Save("video-session.json",r);}}
 public static void SetVrr(bool on){lock(gate){var r=Read();if(!r.VrrSaved){r.VrrSaved=true;r.VrrBefore=WindowsVrr.Token(WindowsVrr.Read());Storage.Save("video-session.json",r);}WindowsVrr.Set(on?"VRROptimizeEnable=1":"VRROptimizeEnable=0");}}
 public static void Restore(){lock(gate){var errors=new List<string>();try{RecoverPending();}catch(Exception e){errors.Add(e.Message);}if(!File.Exists(Storage.PathOf("video-session.json"))){if(errors.Count>0)throw new InvalidOperationException(string.Join("\n",errors));return;}var r=Read();if(r.HdrTarget!=null)try{var target=VideoNative.Resolve(r.HdrTarget);if(VideoNative.Hdr(target).Enabled!=r.HdrBefore)VideoNative.Hdr(target,r.HdrBefore);r.HdrTarget=null;Storage.Save("video-session.json",r);}catch(Exception e){errors.Add(e.Message);}if(r.VrrSaved)try{WindowsVrr.Set(r.VrrBefore);r.VrrSaved=false;Storage.Save("video-session.json",r);}catch(Exception e){errors.Add(e.Message);}if(errors.Count>0)throw new InvalidOperationException(string.Join("\n",errors));File.Delete(Storage.PathOf("video-session.json"));}}
 public static void RecoverPending(){if(!File.Exists(Storage.PathOf("pending-video.json")))return;var p=Storage.Read<VideoPending>("pending-video.json");Rollback(p);File.Delete(Storage.PathOf("pending-video.json"));}
 internal static void Rollback(VideoPending p){var target=VideoNative.Resolve(p.Target);if(p.IsHdr){if(VideoNative.Hdr(target).Enabled!=p.Hdr)VideoNative.Hdr(target,p.Hdr);}else if(VideoNative.Current(target.Device).Key!=p.Mode.Key)VideoNative.Apply(target,p.Mode);}
}
internal sealed class VideoTrial : IDisposable {
 readonly object gate=new object();readonly VideoPending before;readonly Action<VideoPending> rollback;System.Threading.Timer timer;bool finished;public bool Finished{get{lock(gate)return finished;}}public string Error;public DateTime Deadline;
 static VideoPending Before(ScreenTarget target,bool? hdr){var p=new VideoPending{Target=target,Mode=VideoNative.Current(target.Device),IsHdr=hdr.HasValue,Hdr=VideoNative.Hdr(target).Enabled};if(hdr.HasValue)VideoSession.RememberHdr(target);return p;}
 public VideoTrial(ScreenTarget target,VideoMode mode,bool? hdr):this(Before(target,hdr),()=>{if(hdr.HasValue)VideoNative.Hdr(target,hdr.Value);else VideoNative.Apply(target,mode);},VideoSession.Rollback,20000){}
 internal VideoTrial(VideoPending state,Action apply,Action<VideoPending> undo,int milliseconds){before=state;rollback=undo;Deadline=DateTime.UtcNow.AddMilliseconds(milliseconds);Storage.Save("pending-video.json",before);lock(gate){timer=new System.Threading.Timer(delegate{try{Revert();}catch(Exception e){Error=e.Message;Storage.Log(e.ToString());}},null,milliseconds,Timeout.Infinite);try{apply();}catch(Exception error){try{Revert();}catch(Exception recovery){throw new InvalidOperationException(error.Message+" Restore needs attention: "+recovery.Message,error);}throw;}}}
 public bool Confirm(){lock(gate){if(finished)return false;if(DateTime.UtcNow>=Deadline){Revert();return false;}File.Delete(Storage.PathOf("pending-video.json"));finished=true;timer.Dispose();return true;}}
 public void Revert(){lock(gate){if(finished)return;rollback(before);File.Delete(Storage.PathOf("pending-video.json"));finished=true;timer.Dispose();}}
 public void Dispose(){Revert();}
