internal sealed class SessionVolume : IDisposable {
 readonly IAudioEnumerator enumerator;readonly IAudioDevice device;readonly IEndpointVolume volume;
 public SessionVolume(){enumerator=(IAudioEnumerator)new AudioEnumerator();enumerator.GetDefaultAudioEndpoint(0,1,out device);Guid iid=typeof(IEndpointVolume).GUID;object endpoint;device.Activate(ref iid,23,IntPtr.Zero,out endpoint);volume=(IEndpointVolume)endpoint;}
 public int Percent {get{float value;volume.GetMasterVolumeLevelScalar(out value);return (int)Math.Round(value*100);}set{Guid context=Guid.Empty;volume.SetMasterVolumeLevelScalar(Math.Max(0,Math.Min(100,value))/100f,ref context);}}
