internal static class QuickMenuTests {
 public static void Run(){if(Marshal.SizeOf(typeof(VideoMode))!=220)throw new Exception("DEVMODE layout mismatch");string original="GpuPreference=2;VRROptimizeEnable=0;SwapEffectUpgradeEnable=1;";if(WindowsVrr.Replace(original,"VRROptimizeEnable=1")!="GpuPreference=2;SwapEffectUpgradeEnable=1;VRROptimizeEnable=1;")throw new Exception("VRR edit corrupted other GPU preferences");if(WindowsVrr.Replace(original,null)!="GpuPreference=2;SwapEffectUpgradeEnable=1;")throw new Exception("VRR cleanup corrupted other settings");if(WindowsVrr.Token("Other=1;VRROptimizeEnable=1;")!="VRROptimizeEnable=1")throw new Exception("VRR read failed");var targets=VideoNative.Targets();foreach(var target in targets){var current=VideoNative.Current(target.Device);var modes=VideoNative.Modes(target.Device);if(current.Width==0||modes.Count==0)throw new Exception("Display inventory failed");VideoNative.Hdr(target);}using(var volume=new SessionVolume()){int percent=volume.Percent;bool mute=volume.Muted;if(percent<0||percent>100)throw new Exception("Audio inventory failed");}string oldData=Storage.Data,oldVrrPath=WindowsVrr.Path;WindowsVrr.Path=@"Software\SteamCouch\QuickMenuVrrTest-"+Guid.NewGuid().ToString("N");Storage.Data=System.IO.Path.Combine(oldData,"quick-menu-recovery-test");try{int applied=0,reverted=0;var pending=new VideoPending{Target=new ScreenTarget{Device="test",Path="test"}};using(var trial=new VideoTrial(pending,()=>applied++,p=>reverted++,80)){SpinWait.SpinUntil(()=>trial.Finished,2000);if(!trial.Finished||reverted!=1||File.Exists(Storage.PathOf("pending-video.json")))throw new Exception("Watchdog did not roll back");}using(var trial=new VideoTrial(pending,()=>applied++,p=>reverted++,80)){trial.Confirm();Thread.Sleep(150);if(reverted!=1||File.Exists(Storage.PathOf("pending-video.json")))throw new Exception("Confirmed mode was reverted");}using(var trial=new VideoTrial(pending,()=>applied++,p=>reverted++,5000)){trial.Revert();trial.Revert();if(reverted!=2)throw new Exception("Rollback must run once");}bool failed=false;try{new VideoTrial(pending,()=>{throw new Exception("apply failed");},p=>reverted++,5000);}catch{failed=true;}if(!failed||reverted!=3||File.Exists(Storage.PathOf("pending-video.json")))throw new Exception("Failed apply did not restore");failed=false;VideoTrial retry=new VideoTrial(pending,()=>applied++,p=>{if(!failed)throw new Exception("offline");reverted++;},5000);try{retry.Revert();}catch{}if(!File.Exists(Storage.PathOf("pending-video.json"))||retry.Finished)throw new Exception("Failed recovery discarded restore data");failed=true;retry.Revert();retry.Dispose();if(File.Exists(Storage.PathOf("pending-video.json")))throw new Exception("Retry did not clear recovery");var nav=new MenuNavigation();if(nav.Sample(0x1000)!=0)throw new Exception("Held A on open must not activate");nav.Sample(0);if(nav.Sample(0x1000)!=0x1000||nav.Sample(0x1000)!=0)throw new Exception("A edge/rearm failed");if(nav.Sample(2)!=2)throw new Exception("D-pad down mapping failed");using(var key=Registry.CurrentUser.CreateSubKey(WindowsVrr.Path))key.SetValue("DirectXUserGlobalSettings","GpuPreference=2;VRROptimizeEnable=0;",RegistryValueKind.String);VideoSession.SetVrr(true);if(!WindowsVrr.Enabled)throw new Exception("VRR session enable failed");using(var key=Registry.CurrentUser.CreateSubKey(WindowsVrr.Path))key.SetValue("DirectXUserGlobalSettings",WindowsVrr.Read()+"Other=9;",RegistryValueKind.String);VideoSession.Restore();if(WindowsVrr.Enabled||!WindowsVrr.Read().Contains("Other=9;")||!WindowsVrr.Read().Contains("GpuPreference=2;"))throw new Exception("VRR restoration lost unrelated preferences");}finally{Registry.CurrentUser.DeleteSubKeyTree(WindowsVrr.Path,false);WindowsVrr.Path=oldVrrPath;Storage.Data=oldData;}File.WriteAllText(Storage.PathOf("quick-menu-test.txt"),"PASS: DEVMODE structure, VRR token preservation/removal, read-only display mode/HDR inventory, native playback volume/mute queries. Countdown rollback, confirmation, single rollback, apply-failure recovery, retry retention, and controller navigation verified with isolated fake changes. No display or audio mutations performed.");}
}
